import { useCallback, useRef } from 'react';

import { EVENT_ACTIONS } from '@proton/shared/lib/constants';

import { useEventManager } from '../../hooks';

export const interval = 5000;
export const maxPollingSteps = 5;

const hasMatchingEvent = (event: unknown, property: string, action?: EVENT_ACTIONS) => {
    if (typeof event !== 'object' || event === null) {
        return false;
    }

    const propertyEvents = (event as Record<string, unknown>)[property];

    return (
        Array.isArray(propertyEvents) &&
        propertyEvents.some((propertyEvent) => {
            return (
                typeof propertyEvent === 'object' &&
                propertyEvent !== null &&
                (action === undefined || (propertyEvent as { Action?: EVENT_ACTIONS }).Action === action)
            );
        })
    );
};

/**
 * After the Chargebee migration, certain objects aren't immediately updated.
 * For example, it takes a few seconds for updated Subscription object to appear.
 * This time isn't predictable due to async nature of the backend system, so we need to poll for the updated data.
 * */
export const usePollEvents = (property?: string, action?: EVENT_ACTIONS) => {
    const { call, subscribe } = useEventManager();
    const activePolling = useRef<Promise<void> | undefined>(undefined);

    return useCallback(() => {
        if (activePolling.current) {
            return activePolling.current;
        }

        let resolvePolling!: () => void;
        let rejectPolling!: (error: unknown) => void;
        const pollingPromise = new Promise<void>((resolve, reject) => {
            resolvePolling = resolve;
            rejectPolling = reject;
        });
        activePolling.current = pollingPromise;

        let completed = false;
        let pollingSteps = 0;
        let timeout: ReturnType<typeof setTimeout> | undefined;
        let unsubscribe = () => {};

        const cleanup = () => {
            if (timeout !== undefined) {
                clearTimeout(timeout);
                timeout = undefined;
            }

            const unsubscribeCurrent = unsubscribe;
            unsubscribe = () => {};
            try {
                unsubscribeCurrent();
            } catch {
                // The polling promise must settle even if a subscriber throws while unsubscribing.
            }

            if (activePolling.current === pollingPromise) {
                activePolling.current = undefined;
            }
        };

        const finish = () => {
            if (completed) {
                return;
            }
            completed = true;
            cleanup();
            resolvePolling();
        };

        const fail = (error: unknown) => {
            if (completed) {
                return;
            }
            completed = true;
            cleanup();
            rejectPolling(error);
        };

        const poll = async () => {
            if (completed) {
                return;
            }

            timeout = undefined;
            pollingSteps += 1;
            try {
                await call();
            } catch (error) {
                fail(error);
                return;
            }

            if (completed) {
                return;
            }

            if (pollingSteps >= maxPollingSteps) {
                finish();
                return;
            }

            timeout = setTimeout(poll, interval);
        };

        if (property) {
            try {
                const subscribedUnsubscribe = subscribe((event: unknown) => {
                    if (!completed && hasMatchingEvent(event, property, action)) {
                        finish();
                    }
                });
                unsubscribe = subscribedUnsubscribe;

                // A custom event manager may invoke the handler synchronously from subscribe().
                if (completed) {
                    const unsubscribeCurrent = unsubscribe;
                    unsubscribe = () => {};
                    unsubscribeCurrent();
                }
            } catch (error) {
                fail(error);
            }
        }

        if (!completed) {
            timeout = setTimeout(poll, interval);
        }

        return pollingPromise;
    }, [action, call, property, subscribe]);
};

